WITH src AS (SELECT * FROM inventory WHERE product_id IN (4, 7) AND quantity >= 191), inventory_stats AS (SELECT store_id, DATE_TRUNC('MONTH', last_restock) AS last_restock_month, MAX(quantity) - MIN(quantity) AS quantity_range FROM src GROUP BY store_id, DATE_TRUNC('MONTH', last_restock)) SELECT store_id, quantity_range FROM inventory_stats ORDER BY quantity_range DESC, store_id ASC;
